-- Close every temporary Talent Builder popup/window.
function ForeverTalents.CloseAllPopups()
    local names = {
        "textDialog",
        "savedPanel",
        "presetPanel",
        "presetCloseButton",
    }
    for _,name in ipairs(names) do
        local frame = ForeverTalents[name]
        if frame and frame.Hide then frame:Hide() end
        ForeverTalents[name] = nil
    end
end

