    {id=105701,row=2,col=1,icon="Interface\\\\Icons\\\\ability_paladin_judgementblue",maxRank=3,name="Sanctified Judgement",requires={},ranks={{spellId=1311074,name="Sanctified Judgement",description="Gives your Judgement ability a 33% chance to return 20% of the Mana cost of the judged seal."},{spellId=1311074,name="Sanctified Judgement",description="Gives your Judgement ability a 66% chance to return 40% of the Mana cost of the judged seal."},{spellId=1311074,name="Sanctified Judgement",description="Gives your Judgement ability a 100% chance to return 60% of the Mana cost of the judged seal."}}},
    {id=105696,row=2,col=2,icon="Interface\\\\Icons\\\\ability_warrior_innerrage",maxRank=1,name="Seal of Command",requires={},ranks={{spellId=20375,name="Seal of Command",description="Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage.  Only one Seal can be active on the Paladin at any one time.  Lasts 30 sec.\n\nUnleashing this Seal's energy will judge an enemy, instantly causing (42.9% of Spell Power) Holy damage, (42.9% of Spell Power) if the target is stunned or incapacitated."}}},
