    {id=105698,row=3,col=0,icon="Interface\\\\Icons\\\\spell_holy_eyeforaneye",maxRank=2,name="Eye for an Eye",requires={},ranks={{spellId=9799,name="Eye for an Eye",description="All critical strikes against you cause 5% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health."},{spellId=9799,name="Eye for an Eye",description="All critical strikes against you cause 10% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health."}}},
    {id=105700,row=3,col=2,icon="Interface\\\\Icons\\\\inv_sword_08",maxRank=1,name="Sacred Arbiter",requires={},ranks={{spellId=1311087,name="Sacred Arbiter",description="Increases the damage of your Holy Strike ability by 10% and causes it to refresh all Judgement effects on the target."}}},
