    {id=105697,row=4,col=0,icon="Interface\\\\Icons\\\\inv_hammer_04",maxRank=3,name="Two-Handed Weapon Specialization",requires={},ranks={{spellId=20111,name="Two-Handed Weapon Specialization",description="Increases the damage you deal with two-handed melee weapons by 3%."},{spellId=20111,name="Two-Handed Weapon Specialization",description="Increases the damage you deal with two-handed melee weapons by 6%."},{spellId=20111,name="Two-Handed Weapon Specialization",description="Increases the damage you deal with two-handed melee weapons by 9%."}}},
    {id=105693,row=4,col=1,icon="Interface\\\\Icons\\\\ability_racial_avatar",maxRank=3,name="Vengeance",requires={{id=105701,qty=3}},ranks={{spellId=20049,name="Vengeance",description="Increases your Physical and Holy damage dealt by 1% for 30 sec after landing a critical strike.  Stacks up to 5 times."},{spellId=20049,name="Vengeance",description="Increases your Physical and Holy damage dealt by 2% for 30 sec after landing a critical strike.  Stacks up to 5 times."},{spellId=20049,name="Vengeance",description="Increases your Physical and Holy damage dealt by 3% for 30 sec after landing a critical strike.  Stacks up to 5 times."}}},
