    {id=110882,row=5,col=1,icon="Interface\\\\Icons\\\\ability_paladin_enlightenedjudgements",maxRank=3,name="Champion of the Light",requires={},ranks={{spellId=1311084,name="Champion of the Light",description="Increases your spell damage and healing by up to 33% of your Intellect."},{spellId=1311084,name="Champion of the Light",description="Increases your spell damage and healing by up to 66% of your Intellect."},{spellId=1311084,name="Champion of the Light",description="Increases your spell damage and healing by up to 100% of your Intellect."}}},
    {id=110880,row=5,col=2,icon="Interface\\\\Icons\\\\spell_holy_divinepurpose",maxRank=2,name="Instrument of Law",requires={},ranks={{spellId=1311085,name="Instrument of Law",description="Reduces the cast time of your Hammer of Wrath by 0.5 sec, and reduces all threat you generate by 10% while Righteous Fury is not active."},{spellId=1311085,name="Instrument of Law",description="Reduces the cast time of your Hammer of Wrath by 1.0 sec, and reduces all threat you generate by 20% while Righteous Fury is not active."}}},
