    {id=105769,row=3,col=1,icon="Interface\\\\Icons\\\\spell_frost_frost",maxRank=1,name="Ice Block",requires={},ranks={{spellId=11958,name="Ice Block",description="You become encased in a block of ice, protecting you from all physical attacks and spells for 10 sec, but during that time you cannot attack, move, or cast spells."}}},
    {id=105768,row=3,col=3,icon="Interface\\\\Icons\\\\spell_frost_frostshock",maxRank=3,name="Shatter",requires={},ranks={{spellId=11170,name="Shatter",description="Increases the critical strike chance of all your spells against Frozen targets by 17%."},{spellId=11170,name="Shatter",description="Increases the critical strike chance of all your spells against Frozen targets by 33%."},{spellId=11170,name="Shatter",description="Increases the critical strike chance of all your spells against Frozen targets by 50%."}}},
