    {id=105763,row=5,col=2,icon="Interface\\\\Icons\\\\spell_frost_chillingblast",maxRank=5,name="Winter's Chill",requires={},ranks={{spellId=11180,name="Winter's Chill",description="Gives your Frost damage spells a 20% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 1 times."},{spellId=11180,name="Winter's Chill",description="Gives your Frost damage spells a 40% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 2 times."},{spellId=11180,name="Winter's Chill",description="Gives your Frost damage spells a 60% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 3 times."},{spellId=11180,name="Winter's Chill",description="Gives your Frost damage spells a 80% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 4 times."},{spellId=11180,name="Winter's Chill",description="Gives your Frost damage spells a 100% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 5 times."}}},
