    {id=105902,row=1,col=0,icon="Interface\\\\Icons\\\\spell_shadow_ragingscream",maxRank=2,name="Demonic Aegis",requires={},ranks={{spellId=1235316,name="Demonic Aegis",description="Increases the effectiveness of your Demon Skin and Demon Armor spells by 15%."},{spellId=1235316,name="Demonic Aegis",description="Increases the effectiveness of your Demon Skin and Demon Armor spells by 30%."}}},
    {id=105904,row=1,col=1,icon="Interface\\\\Icons\\\\spell_shadow_summonvoidwalker",maxRank=3,name="Improved Voidwalker",requires={},ranks={{spellId=18705,name="Improved Voidwalker",description="Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 10%."},{spellId=18705,name="Improved Voidwalker",description="Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 20%."},{spellId=18705,name="Improved Voidwalker",description="Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 30%."}}},
    {id=105903,row=1,col=2,icon="Interface\\\\Icons\\\\spell_shadow_demonictactics",maxRank=3,name="Fel Vitality",requires={},ranks={{spellId=18731,name="Fel Vitality",description="Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 5%, and increases your maximum Mana by 5%."},{spellId=18731,name="Fel Vitality",description="Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 10%, and increases your maximum Mana by 10%."},{spellId=18731,name="Fel Vitality",description="Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 15%, and increases your maximum Mana by 15%."}}},
    {id=105899,row=1,col=3,icon="Interface\\\\Icons\\\\spell_shadow_felmending",maxRank=2,name="Demonic Energies",requires={},ranks={{spellId=1225214,name="Demonic Energies",description="You heal your pet for 8% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 50% of the Mana you gain."},{spellId=1225214,name="Demonic Energies",description="You heal your pet for 15% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 100% of the Mana you gain."}}},
    {id=105901,row=2,col=0,icon="Interface\\\\Icons\\\\ability_warlock_randomizesuccubusincubus",maxRank=3,name="Improved Sayaad",requires={},ranks={{spellId=18754,name="Improved Sayaad",description="Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 10%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 10%."},{spellId=18754,name="Improved Sayaad",description="Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 20%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 20%."},{spellId=18754,name="Improved Sayaad",description="Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 30%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 30%."}}},
    {id=105900,row=2,col=1,icon="Interface\\\\Icons\\\\spell_shadow_psychicscream",maxRank=1,name="Demonic Sacrifice",requires={},ranks={{spellId=18788,name="Demonic Sacrifice",description="When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts 2 hrs. The effect is canceled if any Demon is summoned.\n\nImp: Increases your Shadow damage by 15%.\n\nVoidwalker: Restores 2% of your total Mana every 4 sec.\n\nSuccubus/Incubus: Increases your Fire damage by 15%.\n\nFelhunter: Restores 3% of your total Health every 4 sec."}}},
    {id=105898,row=2,col=2,icon="Interface\\\\Icons\\\\spell_shadow_impphaseshift",maxRank=2,name="Master Summoner",requires={},ranks={{spellId=18709,name="Master Summoner",description="Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 2 sec and the Mana cost by 20%."},{spellId=18709,name="Master Summoner",description="Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 4 sec and the Mana cost by 40%."}}},
    {id=105897,row=3,col=0,icon="Interface\\\\Icons\\\\spell_fire_fireball02",maxRank=2,name="Decimation",requires={},ranks={{spellId=440870,name="Decimation",description="Reduces the cooldown of your Soul Fire spell by 45%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 3% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 20% and costs no Soul Shards."},{spellId=440870,name="Decimation",description="Reduces the cooldown of your Soul Fire spell by 90%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 6% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 40% and costs no Soul Shards."}}},
    {id=105895,row=3,col=2,icon="Interface\\\\Icons\\\\spell_nature_removecurse",maxRank=1,name="Fel Domination",requires={{id=105898,qty=2}},ranks={{spellId=18708,name="Fel Domination",description="Your next Imp, Voidwalker, Succubus, Incubus, or Felhunter Summon spell has its casting time reduced by 6 sec and its Mana cost reduced by 50%."}}},
    {id=105896,row=3,col=3,icon="Interface\\\\Icons\\\\ability_demonhunter_chaoticimprint_fire",maxRank=3,name="Demonic Brand",requires={},ranks={{spellId=1293695,name="Demonic Brand",description="Your Searing Pain generates 17% less threat and brands the target for 10 sec. Your pet's next 2 attacks against the target generate high threat and deal ((((60 - 26) * 1.5) + 14 + (0.078 * ((Shadow spell power)))) * (1 * 1 * 1)) to ((((60 - 26) * 1.5) + 17 + (0.078 * ((Shadow spell power)))) * (1 * 1 * 1)) Fire or Shadow damage based on the pet."},{spellId=1293695,name="Demonic Brand",description="Your Searing Pain generates 33% less threat and brands the target for 10 sec. Your pet's next 4 attacks against the target generate high threat and deal ((((60 - 26) * 1.5) + 14 + (0.078 * ((Shadow spell power)))) * (1 * 1 * 1)) to ((((60 - 26) * 1.5) + 17 + (0.078 * ((Shadow spell power)))) * (1 * 1 * 1)) Fire or Shadow damage based on the pet."},{spellId=1293695,name="Demonic Brand",description="Your Searing Pain generates 50% less threat and brands the target for 10 sec. Your pet's next 6 attacks against the target generate high threat and deal ((((60 - 26) * 1.5) + 14 + (0.078 * ((Shadow spell power)))) * (1 * 1 * 1)) to ((((60 - 26) * 1.5) + 17 + (0.078 * ((Shadow spell power)))) * (1 * 1 * 1)) Fire or Shadow damage based on the pet."}}},
    {id=105894,row=4,col=0,icon="Interface\\\\Icons\\\\spell_shadow_summonfelhunter",maxRank=3,name="Improved Felhunter",requires={},ranks={{spellId=1225217,name="Improved Felhunter",description="Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 10%, and reduces the cooldown of its Spell Lock by 2 sec."},{spellId=1225217,name="Improved Felhunter",description="Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 20%, and reduces the cooldown of its Spell Lock by 4 sec."},{spellId=1225217,name="Improved Felhunter",description="Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 30%, and reduces the cooldown of its Spell Lock by 6 sec."}}},
    {id=105892,row=4,col=1,icon="Interface\\\\Icons\\\\spell_shadow_gathershadows",maxRank=1,name="Soul Link",requires={{id=105900,qty=1}},ranks={{spellId=19028,name="Soul Link",description="When active, 30% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict 3% more damage. Lasts as long as the Demon is active."}}},
