    texture:SetTexture("Interface\\Glues\\CharacterCreate\\UI-CharacterCreate-Classes")
    if tc then
        texture:SetTexCoord(tc[1],tc[2],tc[3],tc[4])
    else
        texture:SetTexCoord(0,1,0,1)
    end
end

local function GetState(classKey)
    ForeverTalents.state[classKey]=ForeverTalents.state[classKey] or {}
    return ForeverTalents.state[classKey]
end

local function RankOf(state,id)
    return tonumber(state[id]) or 0
end

local function TotalPoints(state)
    local n=0
    for _,rank in pairs(state) do n=n+(tonumber(rank) or 0) end
    return n
end

local function TreePoints(state,tree)
    local n=0
    for _,talent in ipairs(tree.talents) do n=n+RankOf(state,talent.id) end
    return n
end

local function PointsBeforeRow(state,tree,row)
    local n=0
    for _,talent in ipairs(tree.talents) do
        if talent.row < row then n=n+RankOf(state,talent.id) end
    end
    return n
end

local function FindTalent(classData,id)
    for _,tree in ipairs(classData.trees) do
        for _,talent in ipairs(tree.talents) do
            if talent.id==id then return talent,tree end
        end
    end
end

local function RequirementsMet(state,talent)
    for _,req in ipairs(talent.requires or {}) do
        if RankOf(state,req.id) < (req.qty or 1) then return false end
    end
    return true
end

local function CanAdd(classData,state,tree,talent)
    local rank=RankOf(state,talent.id)
    if rank >= talent.maxRank then return false end
    if TotalPoints(state) >= (ForeverTalents.previewCap or ForeverTalents.maxPoints) then return false end
    if PointsBeforeRow(state,tree,talent.row) < (talent.row*5) then return false end
    if not RequirementsMet(state,talent) then return false end
    return true
end

local function StateWouldRemainValid(classData,state,removeID)
    local old=RankOf(state,removeID)
    if old<=0 then return false end
    state[removeID]=old-1

    local valid=true
    for _,tree in ipairs(classData.trees) do
        for _,talent in ipairs(tree.talents) do
            if RankOf(state,talent.id)>0 then
                if PointsBeforeRow(state,tree,talent.row) < (talent.row*5) or not RequirementsMet(state,talent) then
                    valid=false
                    break
                end
            end
        end
        if not valid then break end
    end

    state[removeID]=old
    return valid
end

local TalentLockReason

local function SetTooltip(button,talent,state,tree,classData)
    button:SetScript("OnEnter",function(self)
        if not GameTooltip then return end
        GameTooltip:SetOwner(self,"ANCHOR_RIGHT")
        GameTooltip:SetText(talent.name,1,0.82,0.25)
        local rank=RankOf(state,talent.id)
        GameTooltip:AddLine("Rank "..rank.." / "..talent.maxRank,1,1,1)

        if rank>0 and talent.ranks and talent.ranks[rank] then
            GameTooltip:AddLine(" ")
            GameTooltip:AddLine("Current Rank",0.35,1,0.35)
            GameTooltip:AddLine(talent.ranks[rank].description or "",0.90,0.90,0.90,true)
        end
        if rank<talent.maxRank and talent.ranks and talent.ranks[rank+1] then
            GameTooltip:AddLine(" ")
            GameTooltip:AddLine("Next Rank",1,0.82,0.25)
            GameTooltip:AddLine(talent.ranks[rank+1].description or "",0.90,0.90,0.90,true)
        end

        if talent.row and talent.row>0 then
            GameTooltip:AddLine(" ")
            GameTooltip:AddLine("Requires "..(talent.row*5).." points in "..tree.name,0.75,0.75,0.78)
        end
        for _,req in ipairs(talent.requires or {}) do
            local reqTalent=FindTalent(classData,req.id)
            local reqName=reqTalent and reqTalent.name or ("Talent "..tostring(req.id))
            local met=RankOf(state,req.id)>=(req.qty or 1)
            GameTooltip:AddLine("Requires "..(req.qty or 1).." point"..(((req.qty or 1)==1) and "" or "s").." in "..reqName,
                met and 0.35 or 1,met and 1 or 0.3,met and 0.35 or 0.3)
        end

        local reason=TalentLockReason(classData,state,tree,talent)
        if reason=="PREREQ" then GameTooltip:AddLine("Missing prerequisite",1,0.25,0.25)
        elseif reason=="TIER" then GameTooltip:AddLine("Need more points in this tree",0.75,0.75,0.78)
        elseif reason=="CAP" then GameTooltip:AddLine("Preview level point limit reached",1,0.35,0.25) end

        GameTooltip:AddLine(" ")
        if rank<talent.maxRank then GameTooltip:AddLine("Left Click: Add Rank",0.35,1,0.35) end
        if rank>0 then GameTooltip:AddLine("Right Click: Remove Rank",1,0.45,0.35) end
        GameTooltip:Show()
    end)
    button:SetScript("OnLeave",function() if GameTooltip then GameTooltip:Hide() end end)
end

local function BuildAttributeChangeSummary(classData,state)
    local totals={}
    local specials={}
    for _,tree in ipairs(classData.trees) do
        for _,talent in ipairs(tree.talents) do
            local rank=RankOf(state,talent.id)
            if rank>0 then
                local byTalent=ForeverTalents.statEffects and ForeverTalents.statEffects[talent.id]
                local effect=byTalent and byTalent[rank]
                local hadStat=false
                if effect and effect.stats then
                    for _,v in ipairs(effect.stats) do
                        local key=v.name.."|"..v.unit
                        totals[key]=totals[key] or {name=v.name,value=0,unit=v.unit}
                        totals[key].value=totals[key].value+(tonumber(v.value) or 0)
                        hadStat=true
                    end
                end
                -- Preserve complex effects instead of pretending they are simple stats.
                if effect and effect.description and effect.description~="" and not hadStat then
                    table.insert(specials,talent.name..": "..effect.description)
                end
            end
        end
    end
    local rows={}
    for _,v in pairs(totals) do table.insert(rows,v) end
    table.sort(rows,function(a,b) return a.name<b.name end)
    return rows,specials
end


-- Beta v1.028 builder quality-of-life systems
ForeverTalents.history = ForeverTalents.history or {}
ForeverTalents.redoHistory = ForeverTalents.redoHistory or {}

local function CopyState(state)
    local out={}
    for id,rank in pairs(state or {}) do
        if tonumber(rank) and tonumber(rank)>0 then out[id]=tonumber(rank) end
    end
    return out
end

local function PushHistory(classKey,state)
    ForeverTalents.history[classKey]=ForeverTalents.history[classKey] or {}
    table.insert(ForeverTalents.history[classKey],CopyState(state))
    if #ForeverTalents.history[classKey]>30 then table.remove(ForeverTalents.history[classKey],1) end
    ForeverTalents.redoHistory[classKey]={}
end

local function ReplaceState(classKey,newState)
    ForeverTalents.state[classKey]=CopyState(newState or {})
end

local function ValidateState(classData,state)
    if TotalPoints(state)>ForeverTalents.maxPoints then return false,"Build exceeds 51 points." end
    for _,tree in ipairs(classData.trees) do
        for _,talent in ipairs(tree.talents) do
            local rank=RankOf(state,talent.id)
            if rank<0 or rank>talent.maxRank then return false,"Invalid talent rank." end
            if rank>0 then
                if PointsBeforeRow(state,tree,talent.row)<talent.row*5 then
                    return false,"A talent does not meet its tier requirement."
                end
                if not RequirementsMet(state,talent) then
                    return false,"A prerequisite talent is missing."
                end
            end
        end
    end
    return true
end

local function EncodeBuild(classKey,classData,state)
    local parts={"FB1",classKey}
    for _,tree in ipairs(classData.trees) do
        for _,talent in ipairs(tree.talents) do
            local r=RankOf(state,talent.id)
            if r>0 then table.insert(parts,tostring(talent.id)..":"..tostring(r)) end
        end
    end
    return table.concat(parts,";")
end

local function DecodeBuild(code)
    if type(code)~="string" then return nil,nil,"Invalid build code." end
    local version,classKey=string.match(code,"^([^;]+);([^;]+)")
    if version~="FB1" or not classKey then return nil,nil,"Unknown build code." end
    local classData=ForeverTalents.data[classKey]
    if not classData then return nil,nil,"Unknown class in build code." end
    local allowed={}
    for _,tree in ipairs(classData.trees) do
        for _,talent in ipairs(tree.talents) do allowed[talent.id]=talent.maxRank end
    end
    local state={}
    for id,rank in string.gmatch(code,"(%d+):(%d+)") do
        id=tonumber(id); rank=tonumber(rank)
        if not allowed[id] or rank<1 or rank>allowed[id] then return nil,nil,"Invalid talent in build code." end
        state[id]=rank
    end
    local ok,why=ValidateState(classData,state)
    if not ok then return nil,nil,why end
    return classKey,state
end

local function PresetLibraryForClass(classKey)
    local result={}
    if type(ForeverTalentPresets)~="table" then return result end

    local source=nil
    if type(ForeverTalentPresets.builds)=="table" then
        source=ForeverTalentPresets.builds[classKey]
    end
    if type(source)~="table" then source=ForeverTalentPresets[classKey] end
    if type(source)~="table" then return result end

    local classData=ForeverTalents.data[classKey]
    local allowed={}
    if classData then
        for _,tree in ipairs(classData.trees) do
            for _,talent in ipairs(tree.talents) do allowed[talent.id]=talent.maxRank end
        end
    end

    for _,preset in ipairs(source) do
        if type(preset)=="table" and type(preset.code)=="string" and preset.code~="" then
            -- Presets shipped with ForeverBrowser are trusted addon data.
            -- Parse them directly here instead of hiding the preset if this
            -- legacy client behaves differently inside DecodeBuild/validation.
            local loadedClass=string.match(preset.code,"^FB1;([^;]+);")
            local loadedState={}
            if loadedClass==classKey then
                for id,rank in string.gmatch(preset.code,"(%d+):(%d+)") do
                    id=tonumber(id); rank=tonumber(rank)
                    if allowed[id] and rank>=1 and rank<=allowed[id] then
                        loadedState[id]=rank
                    end
                end
                table.insert(result,{
                    name=tostring(preset.name or "Unnamed Build"),
                    author=tostring(preset.author or "Community"),
                    id=tostring(preset.id or ""),
                    category=tostring(preset.category or "OTHER"),
                    description=tostring(preset.description or ""),
                    code=preset.code,
                    state=loadedState,
                })
            end
        end
    end
    table.sort(result,function(a,b)
        local an=string.lower(a.name or "")
        local bn=string.lower(b.name or "")
        if an==bn then return string.lower(a.author or "")<string.lower(b.author or "") end
        return an<bn
    end)
    return result
end

local function PresetPointSummary(classData,presetState)
    local parts={}
    for _,tree in ipairs(classData.trees) do
        table.insert(parts,tree.name.." "..TreePoints(presetState,tree))
    end
    return table.concat(parts," / ")
end

local function SavedBuildDB()
    ForeverDBDatabase=ForeverDBDatabase or {}
    ForeverDBDatabase.foreverTalentBuilds=ForeverDBDatabase.foreverTalentBuilds or {}
    return ForeverDBDatabase.foreverTalentBuilds
end

local function ShowTextDialog(titleText,initialText,onAccept,acceptText,popupParent)
    if ForeverTalents.textDialog then ForeverTalents.textDialog:Hide() end

    -- Use the same active Talent Builder page as the dialog parent.
    -- This keeps the dialog above the talent contents on the Forever client
    -- without relying on UIParent strata behavior.
    local host = popupParent or UIParent
    local f=CreateFrame("Frame",nil,host)
    ForeverTalents.textDialog=f
    f:SetSize(440,150)
    if popupParent then
        f:SetPoint("CENTER",popupParent,"CENTER",0,80)
        if f.SetFrameLevel and popupParent.GetFrameLevel then
            f:SetFrameLevel(popupParent:GetFrameLevel()+500)
        end
    else
        f:SetPoint("CENTER",UIParent,"CENTER",0,80)
        if f.SetFrameStrata then f:SetFrameStrata("DIALOG") end
    end
    f:EnableMouse(true)
    Background(f,0.025,0.03,0.05,0.98)

    local title=Label(f,titleText,15,{1,0.82,0.25,1})
    title:SetPoint("TOPLEFT",f,"TOPLEFT",16,-14)

    local edit=CreateFrame("EditBox",nil,f)
    edit:SetAutoFocus(false)
    edit:SetSize(405,30)
    edit:SetPoint("TOPLEFT",f,"TOPLEFT",16,-48)
    edit:SetFontObject(GameFontHighlightSmall)
    edit:SetTextInsets(8,8,0,0)
    Background(edit,0.01,0.012,0.02,1)
    edit:SetText(initialText or "")
    edit:HighlightText()

    local function CloseDialog()
        edit:ClearFocus()
        f:Hide()
    end

    local ok=CreateFrame("Button",nil,f)
    ok:SetSize(100,28)
    ok:SetPoint("BOTTOMRIGHT",f,"BOTTOMRIGHT",-16,14)
    ok:EnableMouse(true)
    if ok.SetFrameLevel and f.GetFrameLevel then ok:SetFrameLevel(f:GetFrameLevel()+20) end
    Background(ok,0.04,0.12,0.05,1)
    local ot=Label(ok,acceptText or "OK",11,{0.45,1,0.5,1})
    ot:SetPoint("CENTER")
    ok:SetScript("OnMouseDown",function()
        if onAccept then
            local value=edit:GetText() or ""
            onAccept(value)
        end
        CloseDialog()
    end)

    local cancel=CreateFrame("Button",nil,f)
    cancel:SetSize(90,28)
    cancel:EnableMouse(true)
    if cancel.SetFrameLevel and f.GetFrameLevel then cancel:SetFrameLevel(f:GetFrameLevel()+20) end
    Background(cancel,0.10,0.035,0.035,1)
    local ct=Label(cancel,"CLOSE",11,{1,0.55,0.45,1})
    ct:SetPoint("CENTER")
    cancel:SetScript("OnMouseDown",CloseDialog)

    if onAccept then
        cancel:SetPoint("RIGHT",ok,"LEFT",-8,0)
    else
        ok:Hide()
        cancel:SetPoint("BOTTOMRIGHT",f,"BOTTOMRIGHT",-16,14)
    end

    edit:SetScript("OnEscapePressed",CloseDialog)
    edit:SetScript("OnEnterPressed",function()
        if onAccept then
            local value=edit:GetText() or ""
            onAccept(value)
        end
        CloseDialog()
    end)
    edit:SetFocus()
    return f,edit
end

TalentLockReason=function(classData,state,tree,talent)
    local rank=RankOf(state,talent.id)
    if rank>=talent.maxRank then return "MAX" end
    if TotalPoints(state)>=(ForeverTalents.previewCap or ForeverTalents.maxPoints) then return "CAP" end
    if not RequirementsMet(state,talent) then return "PREREQ" end
    if PointsBeforeRow(state,tree,talent.row)<talent.row*5 then return "TIER" end
    return "AVAILABLE"
end

local function DrawConnector(tree,fromTalent,toTalent,active)
    local x1=22+(fromTalent.col*61)+21
    local y1=-50-(fromTalent.row*55)-21
    local x2=22+(toTalent.col*61)+21
    local y2=-50-(toTalent.row*55)-21
    local r,g,b,a
    if active then r,g,b,a=0.95,0.75,0.18,0.9 else r,g,b,a=0.28,0.30,0.34,0.75 end
    local midY=(y1+y2)/2
    local function seg(x,y,w,h)
        local t=tree:CreateTexture(nil,"BORDER")
        t:SetTexture("Interface\\Buttons\\WHITE8X8"); t:SetVertexColor(r,g,b,a)
        t:SetPoint("TOPLEFT",tree,"TOPLEFT",x,y); t:SetSize(math.max(w,2),math.max(h,2))
    end
    seg(x1-1,math.max(y1,midY),2,math.abs(y1-midY))
    seg(math.min(x1,x2),midY+1,math.abs(x2-x1)+2,2)
    seg(x2-1,math.max(y2,midY),2,math.abs(y2-midY))
end

function ForeverTalents.BuildHome(ctx)
    ForeverTalents.CloseAllPopups()
    local parent=ctx.PageContent
    ctx.ClearPage()

    -- Cinematic landing page: self-contained, no external textures required.
    local hero=CreateFrame("Frame",nil,parent)
    hero:SetPoint("TOPLEFT",parent,"TOPLEFT",8,-8)
    hero:SetPoint("TOPRIGHT",parent,"TOPRIGHT",-8,-8)
    hero:SetHeight(405)

    local backdrop=hero:CreateTexture(nil,"BACKGROUND")
    backdrop:SetAllPoints(hero)
    backdrop:SetTexture("Interface\\Glues\\LoadingScreens\\LoadScreenKalimdor")
    backdrop:SetTexCoord(0,1,0,1)
