function ForeverTalents.BuildClass(ctx,classKey)
    local parent=ctx.PageContent

    -- If the user leaves the Talent Builder, automatically close every
    -- Talent Builder popup opened by SAVED / SAVE / PRESETS / COPY / LOAD.
    if parent and not parent._ForeverTalentPopupCleanup then
        parent._ForeverTalentPopupCleanup = true
        parent:HookScript("OnHide",function()
            ForeverTalents.CloseAllPopups()
        end)
    end
    ctx.ClearPage()

    local classData=ForeverTalents.data[classKey]
    if not classData then ForeverTalents.BuildHome(ctx) return end
    local state=GetState(classKey)
    local previewLevel=math.max(10,math.min(60,tonumber(ForeverTalents.previewLevels[classKey]) or 60))
    ForeverTalents.previewCap=math.min(ForeverTalents.maxPoints,previewLevel-9)

    local back=CreateFrame("Button",nil,parent)
    back:SetSize(90,28); back:SetPoint("TOPLEFT",parent,"TOPLEFT",20,-18)
    Background(back,0.025,0.03,0.05,1)
    local bt=Label(back,"< CLASSES",10,{1,0.82,0.25,1}); bt:SetPoint("CENTER")
    back:SetScript("OnClick",function() ctx.Navigate("forever://talents") end)

    local function SmallTopButton(text,x,w,color,click)
        local b=CreateFrame("Button",nil,parent); b:SetSize(w or 70,28)
        b:SetPoint("TOPRIGHT",parent,"TOPRIGHT",x,-18)
        Background(b,color[1],color[2],color[3],1)
        local t=Label(b,text,10,color[4]); t:SetPoint("CENTER")
        b:SetScript("OnClick",click); return b
    end

    SmallTopButton("RESET",-20,64,{0.08,0.025,0.025,{1,0.45,0.35,1}},function()
        if TotalPoints(state)>0 then PushHistory(classKey,state) end
        ForeverTalents.state[classKey]={}
        ForeverTalents.BuildClass(ctx,classKey)
    end)

    SmallTopButton("REDO",-90,58,{0.035,0.045,0.07,{0.72,0.78,0.95,1}},function()
        local stack=ForeverTalents.redoHistory[classKey] or {}
        if #stack>0 then
            ForeverTalents.history[classKey]=ForeverTalents.history[classKey] or {}
            table.insert(ForeverTalents.history[classKey],CopyState(state))
            ReplaceState(classKey,table.remove(stack))
            ForeverTalents.BuildClass(ctx,classKey)
        end
    end)

    SmallTopButton("UNDO",-154,58,{0.035,0.045,0.07,{0.72,0.78,0.95,1}},function()
        local stack=ForeverTalents.history[classKey] or {}
        if #stack>0 then
            ForeverTalents.redoHistory[classKey]=ForeverTalents.redoHistory[classKey] or {}
            table.insert(ForeverTalents.redoHistory[classKey],CopyState(state))
            ReplaceState(classKey,table.remove(stack))
            ForeverTalents.BuildClass(ctx,classKey)
        end
    end)

    SmallTopButton("LOAD",-218,58,{0.035,0.06,0.075,{0.45,0.85,1,1}},function()
        ShowTextDialog("LOAD BUILD CODE","",function(code)
            local loadedClass,loadedState,why=DecodeBuild(code)
            if loadedClass and loadedState then
                if loadedClass~=classKey then
                    ReplaceState(loadedClass,loadedState)
                    ctx.Navigate("forever://talents/"..loadedClass)
                else
                    PushHistory(classKey,state); ReplaceState(classKey,loadedState)
                    ForeverTalents.BuildClass(ctx,classKey)
                end
            elseif DEFAULT_CHAT_FRAME then DEFAULT_CHAT_FRAME:AddMessage("|cffff5555Forever Talents:|r "..tostring(why or "Invalid build code.")) end
        end,"LOAD",parent)
    end)

    SmallTopButton("COPY",-282,58,{0.035,0.06,0.075,{0.45,0.85,1,1}},function()
        local code=EncodeBuild(classKey,classData,state)
        local _,edit=ShowTextDialog("COPY BUILD CODE",code,nil,"CLOSE",parent)
        edit:HighlightText()
    end)

    -- Full preset library.  It can browse every class without leaving the
    -- current Talent Builder page.
    local function OpenPresetBrowser(selectedClassKey)
        if ForeverTalents.presetPanel then ForeverTalents.presetPanel:Hide() end
        if ForeverTalents.presetCloseButton then ForeverTalents.presetCloseButton:Hide() end

        local selectedData=ForeverTalents.data[selectedClassKey]
        if not selectedData then return end

        local f=CreateFrame("Frame",nil,UIParent); ForeverTalents.presetPanel=f
        if f.SetToplevel then f:SetToplevel(true) end
        if f.SetFrameStrata then f:SetFrameStrata("FULLSCREEN_DIALOG") end
        if f.SetFrameLevel then f:SetFrameLevel(10000) end
        f:SetSize(620,500)
        f:SetPoint("CENTER",UIParent,"CENTER",0,30)
        f:SetMovable(false)
        f:EnableMouse(false)
        if f.SetClampedToScreen then f:SetClampedToScreen(true) end
        Background(f,0.025,0.03,0.05,0.99)

        local tt=Label(f,"TALENT PRESET LIBRARY",15,{1,0.82,0.25,1})
        tt:SetPoint("TOPLEFT",f,"TOPLEFT",16,-14)
        local subtitle=Label(f,"Shared builds included with ForeverBrowser",10,{0.62,0.66,0.74,1})
        subtitle:SetPoint("TOPLEFT",tt,"BOTTOMLEFT",0,-5)

        -- Class selector: 5 buttons on row one, 4 on row two.
        local classOrder={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"}
        for i,key in ipairs(classOrder) do
            local cd=ForeverTalents.data[key]
            local col=(i-1)%5
            local row=math.floor((i-1)/5)
            local b=CreateFrame("Button",nil,f)
            b:SetSize(108,25)
            b:SetPoint("TOPLEFT",f,"TOPLEFT",16+(col*116),-58-(row*30))
            b:EnableMouse(true)
            if b.SetFrameLevel and f.GetFrameLevel then b:SetFrameLevel(f:GetFrameLevel()+50) end
            if key==selectedClassKey then
                Background(b,0.12,0.09,0.025,1)
            else
                Background(b,0.035,0.045,0.065,1)
            end
            local bt=Label(b,string.upper(cd.name),9,key==selectedClassKey and {1,0.82,0.25,1} or {0.72,0.78,0.90,1})
            bt:SetPoint("CENTER")
            b:SetScript("OnMouseDown",function() OpenPresetBrowser(key) end)
        end

        local section=Label(f,string.upper(selectedData.name).." PRESETS",13,{1,0.82,0.25,1})
        section:SetPoint("TOPLEFT",f,"TOPLEFT",18,-126)

        local presets=PresetLibraryForClass(selectedClassKey)
        if #presets==0 then
            local none=Label(f,"No shared presets have been included for this class yet.",11,{0.72,0.75,0.82,1})
            none:SetPoint("TOPLEFT",f,"TOPLEFT",18,-158)
            local hint=Label(f,"Use SUBMIT on a finished build to create a submission code for the maintainer.",10,{0.52,0.56,0.64,1})
            hint:SetPoint("TOPLEFT",none,"BOTTOMLEFT",0,-10)
        else
            for i,preset in ipairs(presets) do
                if i<=7 then
                    local row=CreateFrame("Frame",nil,f)
                    row:SetSize(584,42)
                    row:SetPoint("TOPLEFT",f,"TOPLEFT",18,-154-((i-1)*45))
                    Background(row,0.035,0.042,0.065,1)

                    local nm=Label(row,preset.name,10,{0.95,0.90,0.62,1})
                    nm:SetPoint("TOPLEFT",row,"TOPLEFT",8,-6)

                    local category=tostring(preset.category or "OTHER")
                    local meta=Label(row,"by "..preset.author.."  -  "..PresetPointSummary(selectedData,preset.state).."  ["..category.."]",9,{0.62,0.68,0.78,1})
                    meta:SetPoint("TOPLEFT",nm,"BOTTOMLEFT",0,-3)

                    local load=CreateFrame("Button",nil,row)
                    load:SetSize(54,26)
                    load:SetPoint("RIGHT",row,"RIGHT",-6,0)
                    load:EnableMouse(true)
                    if load.SetFrameLevel and row.GetFrameLevel then load:SetFrameLevel(row:GetFrameLevel()+20) end
                    Background(load,0.035,0.09,0.12,1)
                    local lt=Label(load,"LOAD",9,{0.45,0.85,1,1}); lt:SetPoint("CENTER")
                    load:SetScript("OnMouseDown",function()
                        PushHistory(selectedClassKey,ForeverTalents.state[selectedClassKey] or {})
                        ReplaceState(selectedClassKey,CopyState(preset.state))
                        f:Hide()
                        if ForeverTalents.presetCloseButton then ForeverTalents.presetCloseButton:Hide() end
                        if selectedClassKey~=classKey then
                            ctx.Navigate("forever://talents/"..selectedClassKey)
                        else
                            ForeverTalents.BuildClass(ctx,selectedClassKey)
                        end
                    end)
                end
            end
            if #presets>7 then
                local more=Label(f,"Showing 7 of "..#presets.." presets.",9,{0.52,0.56,0.64,1})
                more:SetPoint("BOTTOMLEFT",f,"BOTTOMLEFT",18,14)
            end
        end

        -- Keep the proven separate close control used by the current build.
        local close=CreateFrame("Button",nil,UIParent)
        ForeverTalents.presetCloseButton=close
        close:SetSize(90,34)
        close:SetPoint("TOPRIGHT",f,"TOPRIGHT",-8,-8)
        close:EnableMouse(true)
        if close.SetFrameStrata then close:SetFrameStrata("FULLSCREEN_DIALOG") end
        if close.SetFrameLevel then close:SetFrameLevel(30000) end
        Background(close,0.22,0.025,0.025,1)
        local closeText=Label(close,"CLOSE",11,{1,0.65,0.60,1})
        closeText:SetPoint("CENTER")
        close:SetScript("OnMouseDown",function()
            close:Hide()
            f:Hide()
        end)
    end

    SmallTopButton("PRESETS",-410,58,{0.055,0.05,0.025,{1,0.82,0.25,1}},function()
        if ForeverTalents.presetPanel and ForeverTalents.presetPanel:IsShown() then
            ForeverTalents.presetPanel:Hide()
            if ForeverTalents.presetCloseButton then ForeverTalents.presetCloseButton:Hide() end
            return
        end
        OpenPresetBrowser(classKey)
    end)

    -- SUBMIT creates one compact code that a player can send to the
    -- ForeverBrowser maintainer for review and inclusion in the shared library.
    -- It does not upload anything automatically.
    SmallTopButton("SUBMIT",-346,58,{0.035,0.075,0.055,{0.55,1,0.72,1}},function()
        local buildCode=EncodeBuild(classKey,classData,state)

        ShowTextDialog("SUBMIT BUILD - BUILD NAME",classData.name.." Build",function(buildName)
            buildName=string.gsub(buildName or "","^%s*(.-)%s*$","%1")
            if buildName=="" then buildName=classData.name.." Build" end

            ShowTextDialog("SUBMIT BUILD - AUTHOR","",function(author)
                author=string.gsub(author or "","^%s*(.-)%s*$","%1")
                if author=="" then author="Unknown" end

                ShowTextDialog("CATEGORY - PVE / PVP / LEVELING / OTHER","OTHER",function(category)
                    category=string.upper(string.gsub(category or "","^%s*(.-)%s*$","%1"))
                    if category~="PVE" and category~="PVP" and category~="LEVELING" and category~="OTHER" then
                        category="OTHER"
                    end

                    ShowTextDialog("SUBMIT BUILD - DESCRIPTION","",function(description)
                        description=string.gsub(description or "","^%s*(.-)%s*$","%1")

                        -- Escape fields so semicolons/backslashes cannot break the code.
                        local function EscapeSubmitField(v)
                            v=tostring(v or "")
                            v=string.gsub(v,"\\","\\\\")
                            v=string.gsub(v,";","\\;")
                            v=string.gsub(v,"\r"," ")
                            v=string.gsub(v,"\n"," ")
                            return v
                        end

                        -- FBS1 = ForeverBrowser Submission format version 1.
                        local submission=
                            "FBS1;"..
                            EscapeSubmitField(classKey)..";"..
                            EscapeSubmitField(buildName)..";"..
                            EscapeSubmitField(author)..";"..
                            EscapeSubmitField(category)..";"..
                            EscapeSubmitField(description)..";"..
                            EscapeSubmitField(buildCode)

                        local _,edit=ShowTextDialog(
                            "SUBMISSION CODE - COPY AND SEND TO MAINTAINER",
                            submission,
                            nil,
                            "CLOSE",
                            parent
                        )
                        edit:HighlightText()

                        if DEFAULT_CHAT_FRAME then
                            DEFAULT_CHAT_FRAME:AddMessage("|cff55ff88ForeverBrowser:|r Submission code created. Copy it and send it to the addon maintainer.")
                        end
                    end,"NEXT",parent)
                end,"NEXT",parent)
            end,"NEXT",parent)
        end,"NEXT",parent)
    end)

    SmallTopButton("SAVE",-474,58,{0.035,0.09,0.045,{0.45,1,0.5,1}},function()
        ShowTextDialog("SAVE BUILD AS","",function(name)
            name=string.gsub(name or "","^%s*(.-)%s*$","%1")
            if name=="" then name=classData.name.." Build" end
            local db=SavedBuildDB(); db[classKey]=db[classKey] or {}
            db[classKey][name]=EncodeBuild(classKey,classData,state)
            ForeverTalents.BuildClass(ctx,classKey)
        end,"SAVE",parent)
    end)

    SmallTopButton("COMPARE",-602,60,{0.05,0.055,0.10,{0.72,0.86,1,1}},function()
        ShowTextDialog("COMPARE TO BUILD CODE","",function(code)
            local otherClass,otherState,err=DecodeBuild(code)
            if not otherClass then
                if DEFAULT_CHAT_FRAME then DEFAULT_CHAT_FRAME:AddMessage("Forever Talents: "..tostring(err)) end
                return
            end
            if otherClass~=classKey then
                if DEFAULT_CHAT_FRAME then DEFAULT_CHAT_FRAME:AddMessage("Forever Talents: compare builds from the same class.") end
                return
            end
            local lines={"CURRENT vs IMPORTED BUILD"}
            for _,tr in ipairs(classData.trees) do
                table.insert(lines,tr.name..": "..TreePoints(state,tr).." vs "..TreePoints(otherState,tr))
                for _,talent in ipairs(tr.talents) do
                    local a,b=RankOf(state,talent.id),RankOf(otherState,talent.id)
                    if a~=b then table.insert(lines,talent.name..": "..a.." -> "..b) end
                end
            end
            local report=table.concat(lines,"  |  ")
            ShowTextDialog("BUILD COMPARISON",report,nil,"CLOSE",parent)
        end,"COMPARE",parent)
    end)

    SmallTopButton("SAVED",-538,58,{0.055,0.05,0.025,{1,0.82,0.25,1}},function()
        if ForeverTalents.savedPanel then ForeverTalents.savedPanel:Hide() end
        local f=CreateFrame("Frame",nil,UIParent); ForeverTalents.savedPanel=f
        if f.SetToplevel then f:SetToplevel(true) end
        if f.SetFrameStrata then f:SetFrameStrata("FULLSCREEN_DIALOG") end
        if f.SetFrameLevel then f:SetFrameLevel(10000) end
        f:SetSize(390,360); f:SetPoint("CENTER",UIParent,"CENTER",0,30)
        f:SetMovable(true); f:EnableMouse(true)
        if f.SetClampedToScreen then f:SetClampedToScreen(true) end
        Background(f,0.025,0.03,0.05,0.99)
        local drag=CreateFrame("Frame",nil,f)
        drag:SetPoint("TOPLEFT",f,"TOPLEFT",0,0); drag:SetPoint("TOPRIGHT",f,"TOPRIGHT",0,0); drag:SetHeight(42)
        drag:EnableMouse(true); drag:RegisterForDrag("LeftButton")
        drag:SetScript("OnDragStart",function() f:StartMoving() end)
        drag:SetScript("OnDragStop",function() f:StopMovingOrSizing() end)
        local tt=Label(f,"SAVED "..string.upper(classData.name).." BUILDS",15,{1,0.82,0.25,1}); tt:SetPoint("TOPLEFT",f,"TOPLEFT",16,-14)
        local close=CreateFrame("Button",nil,f); close:SetSize(24,24); close:SetPoint("TOPRIGHT",f,"TOPRIGHT",-10,-9)
        close:EnableMouse(true)
        if close.SetFrameStrata then close:SetFrameStrata("FULLSCREEN_DIALOG") end
        if close.SetFrameLevel and f.GetFrameLevel then close:SetFrameLevel(f:GetFrameLevel()+50) end
        local xt=Label(close,"X",12,{1,0.5,0.4,1}); xt:SetPoint("CENTER"); close:SetScript("OnClick",function() f:Hide() end)
        local save=CreateFrame("Button",nil,f); save:SetSize(105,26); save:SetPoint("TOPRIGHT",f,"TOPRIGHT",-42,-42)
        Background(save,0.04,0.12,0.05,1); local st=Label(save,"SAVE CURRENT",10,{0.45,1,0.5,1}); st:SetPoint("CENTER")
        save:SetScript("OnClick",function()
            ShowTextDialog("SAVE BUILD AS","",function(name)
                name=string.gsub(name or "","^%s*(.-)%s*$","%1")
                if name=="" then name=classData.name.." Build" end
                local db=SavedBuildDB(); db[classKey]=db[classKey] or {}
                db[classKey][name]=EncodeBuild(classKey,classData,state)
                f:Hide(); ForeverTalents.BuildClass(ctx,classKey)
            end,"SAVE",parent)
        end)
        local db=SavedBuildDB(); local builds=db[classKey] or {}; local names={}
        for name in pairs(builds) do table.insert(names,name) end
        table.sort(names)
        if #names==0 then
            local none=Label(f,"No saved builds yet.",11,{0.65,0.68,0.75,1}); none:SetPoint("TOPLEFT",f,"TOPLEFT",18,-84)
        else
            for i,name in ipairs(names) do
                if i<=8 then
                    local row=CreateFrame("Button",nil,f); row:SetSize(350,28); row:SetPoint("TOPLEFT",f,"TOPLEFT",18,-78-((i-1)*32))
                    Background(row,0.035,0.042,0.065,1)
                    local nm=Label(row,name,10,{0.92,0.93,0.96,1}); nm:SetPoint("LEFT",row,"LEFT",8,0)
                    local load=Label(row,"LOAD",9,{0.45,0.85,1,1}); load:SetPoint("RIGHT",row,"RIGHT",-42,0)
                    local del=CreateFrame("Button",nil,row); del:SetSize(28,22); del:SetPoint("RIGHT",row,"RIGHT",-4,0)
                    local dt=Label(del,"X",9,{1,0.4,0.35,1}); dt:SetPoint("CENTER")
                    del:SetScript("OnClick",function()
                        builds[name]=nil; f:Hide(); ForeverTalents.BuildClass(ctx,classKey)
                    end)
                    row:SetScript("OnClick",function()
                        local lc,ls=DecodeBuild(builds[name])
                        if lc and ls then PushHistory(classKey,state); ReplaceState(classKey,ls); f:Hide(); ForeverTalents.BuildClass(ctx,classKey) end
                    end)
                end
            end
        end
    end)

    local icon=parent:CreateTexture(nil,"ARTWORK"); icon:SetSize(42,42); icon:SetPoint("TOPLEFT",parent,"TOPLEFT",20,-58); SetClassIcon(icon,classKey)
    local title=Label(parent,classData.name.." TALENTS",20,{1,0.82,0.25,1}); title:SetPoint("LEFT",icon,"RIGHT",12,5)

    local summary={}
