    local points=Label(parent,table.concat(summary,"  •  ").."  •  Total "..TotalPoints(state).."/"..ForeverTalents.maxPoints,11,{0.75,0.78,0.85,1})
    points:SetPoint("TOPLEFT",title,"BOTTOMLEFT",0,-4)

    -- Level preview and safe point-cap control. Lowering a level never destroys a build.
