    LevelButton("-",290,-1)
    LevelButton("+",320,1)
    local caution=Label(parent,"Preview only; existing builds above the selected level remain saved.",9,{0.65,0.69,0.74,1})
    caution:SetPoint("TOPLEFT",parent,"TOPLEFT",360,-122)

    local treeW,treeH,startY=286,455,-165
    for ti,treeData in ipairs(classData.trees) do
        local tree=CreateFrame("Frame",nil,parent); tree:SetSize(treeW,treeH); tree:SetScale(0.95); tree:SetPoint("TOPLEFT",parent,"TOPLEFT",20+((ti-1)*295),startY)
        Background(tree,0.018,0.022,0.035,0.98)
        -- Classic WoW talent art is stored as four separate texture quadrants.
        -- Names follow Interface\TalentFrame\<Class><Specialization>-TopLeft, etc.
        -- Keep the existing dark panel as a fallback if the client lacks artwork.
        local artwork=CreateFrame("Frame",nil,tree)
        artwork:SetPoint("TOPLEFT",tree,"TOPLEFT",3,-55)
        artwork:SetPoint("BOTTOMRIGHT",tree,"BOTTOMRIGHT",-3,3)
        artwork:SetFrameLevel(tree:GetFrameLevel())
        local classNames={SHAMAN="Shaman",MAGE="Mage",WARRIOR="Warrior",
            PRIEST="Priest",ROGUE="Rogue",DRUID="Druid",HUNTER="Hunter",
            WARLOCK="Warlock",PALADIN="Paladin"}
        local className=classNames[string.upper(classKey or "")] or "Shaman"
        local specName=(treeData.name or ""):gsub("[^%a]","")
        local prefix="Interface\\TalentFrame\\"..className..specName.."-"
        local quadrants={
            {"TopLeft","TOPLEFT",0,0},
            {"TopRight","TOPRIGHT",0,0},
            {"BottomLeft","BOTTOMLEFT",0,0},
            {"BottomRight","BOTTOMRIGHT",0,0},
        }
        for _,part in ipairs(quadrants) do
            local tex=artwork:CreateTexture(nil,"BACKGROUND",nil,1)
            tex:SetSize(140,198)
            tex:SetPoint(part[2],artwork,part[2],part[3],part[4])
            tex:SetTexture(prefix..part[1])
            tex:SetVertexColor(1,1,1,1)
        end
        local wash=artwork:CreateTexture(nil,"BACKGROUND",nil,2)
        wash:SetAllPoints(artwork)
        wash:SetTexture("Interface\\Buttons\\WHITE8X8")
        wash:SetVertexColor(0,0,0,0.28)

        local treeIcon=tree:CreateTexture(nil,"ARTWORK"); treeIcon:SetSize(24,24); treeIcon:SetPoint("TOPLEFT",tree,"TOPLEFT",12,-10); treeIcon:SetTexture(treeData.icon)
        local treeTitle=Label(tree,treeData.name,14,{1,0.82,0.25,1}); treeTitle:SetPoint("LEFT",treeIcon,"RIGHT",7,0)
        local treePts=Label(tree,TreePoints(state,treeData).." points",10,{0.65,0.68,0.75,1}); treePts:SetPoint("TOPRIGHT",tree,"TOPRIGHT",-12,-16)
        local resetTree=CreateFrame("Button",nil,tree)
        resetTree:SetSize(70,18)
        resetTree:SetPoint("TOPRIGHT",tree,"TOPRIGHT",-8,-32)
        Background(resetTree,0.12,0.035,0.035,1)
        local resetLabel=Label(resetTree,"RESET TREE",9,{1,0.55,0.45,1})
        resetLabel:SetPoint("CENTER")
        resetTree:SetScript("OnClick",function()
            if TreePoints(state,treeData)==0 then return end
            PushHistory(classKey,state)
            for _,talent in ipairs(treeData.talents) do state[talent.id]=nil end
            ForeverTalents.BuildClass(ctx,classKey)
        end)

        -- Tier markers make the 5-point progression visible.
        for tier=0,6 do
            local marker=Label(tree,tostring(tier*5),8,{0.38,0.41,0.48,1})
            marker:SetPoint("TOPRIGHT",tree,"TOPRIGHT",-4,-63-(tier*55))
        end

        -- Prerequisite connectors are drawn before buttons so icons remain on top.
        for _,talent in ipairs(treeData.talents) do
            for _,req in ipairs(talent.requires or {}) do
                local fromTalent,fromTree=FindTalent(classData,req.id)
                if fromTalent and fromTree==treeData then
                    DrawConnector(tree,fromTalent,talent,RankOf(state,req.id)>=(req.qty or 1))
                end
            end
        end

        for _,talent in ipairs(treeData.talents) do
            local b=CreateFrame("Button",nil,tree); b:SetSize(42,42); b:SetPoint("TOPLEFT",tree,"TOPLEFT",22+(talent.col*61),-50-(talent.row*55))
            if b.RegisterForClicks then b:RegisterForClicks("LeftButtonUp","RightButtonUp") end

            local border=b:CreateTexture(nil,"BACKGROUND"); border:SetTexture("Interface\\Buttons\\WHITE8X8")
            border:SetPoint("TOPLEFT",b,"TOPLEFT",-2,2); border:SetPoint("BOTTOMRIGHT",b,"BOTTOMRIGHT",2,-2)

            local tex=b:CreateTexture(nil,"ARTWORK"); tex:SetAllPoints(b)
            local resolvedTalentIcon=nil
            if C_Spell and C_Spell.GetSpellTexture and talent.ranks and talent.ranks[1] then
                local ok,value=pcall(C_Spell.GetSpellTexture,talent.ranks[1].spellId); if ok then resolvedTalentIcon=value end
            end
            if resolvedTalentIcon then tex:SetTexture(resolvedTalentIcon) else tex:SetTexture(talent.icon) end

            local rank=RankOf(state,talent.id)
            local reason=TalentLockReason(classData,state,treeData,talent)
            if rank>=talent.maxRank then border:SetVertexColor(1,0.78,0.12,1)
            elseif rank>0 then border:SetVertexColor(0.2,0.9,0.3,1)
            elseif reason=="AVAILABLE" then border:SetVertexColor(0.35,0.75,1,1)
            elseif reason=="PREREQ" then border:SetVertexColor(0.75,0.15,0.15,1)
            else border:SetVertexColor(0.28,0.30,0.34,1) end

            local shade=b:CreateTexture(nil,"OVERLAY"); shade:SetTexture("Interface\\Buttons\\WHITE8X8"); shade:SetAllPoints(b)
            if rank>0 then shade:SetVertexColor(0,0,0,0)
            elseif reason=="AVAILABLE" then shade:SetVertexColor(0,0,0,0.12)
            else shade:SetVertexColor(0,0,0,0.62) end

            local rankBG=CreateFrame("Frame",nil,b); rankBG:SetFrameLevel(b:GetFrameLevel()+3); rankBG:SetSize(27,16); rankBG:SetPoint("BOTTOMRIGHT",b,"BOTTOMRIGHT",4,-3)
            local rbg=Background(rankBG,0.01,0.01,0.01,0.96)
            if rank>=talent.maxRank then rbg:SetVertexColor(0.20,0.14,0.01,0.98) end
            local rankColor=rank>=talent.maxRank and {1,0.82,0.18,1} or (rank>0 and {0.35,1,0.35,1} or {0.75,0.75,0.75,1})
            local rankText=Label(rankBG,rank.."/"..talent.maxRank,10,rankColor); rankText:SetPoint("CENTER")

            SetTooltip(b,talent,state,treeData,classData)
            b:SetScript("OnClick",function(self,mouseButton)
                local current=RankOf(state,talent.id)
                if mouseButton=="RightButton" then
                    if current>0 and StateWouldRemainValid(classData,state,talent.id) then
                        PushHistory(classKey,state); state[talent.id]=current-1; ForeverTalents.BuildClass(ctx,classKey)
                    end
                elseif CanAdd(classData,state,treeData,talent) then
                    PushHistory(classKey,state); state[talent.id]=current+1; ForeverTalents.BuildClass(ctx,classKey)
                end
            end)
        end
    end

    local help=Label(parent,"Blue = available   Gold = max rank   Red = missing prerequisite   Gray = tier locked     Left-click add • Right-click remove",10,{0.62,0.66,0.74,1})
    help:SetPoint("TOPLEFT",parent,"TOPLEFT",20,-604); help:SetWidth(875); help:SetJustifyH("LEFT")
    local summaryTitle=Label(parent,"BUILD SUMMARY",14,{1,0.82,0.25,1})
    summaryTitle:SetPoint("TOPLEFT",parent,"TOPLEFT",20,-632)
    local summaryParts={}
    for _,tr in ipairs(classData.trees) do
        local selected={}
        for _,talent in ipairs(tr.talents) do
            local rank=RankOf(state,talent.id)
            if rank>0 then table.insert(selected,talent.name.." "..rank.."/"..talent.maxRank) end
        end
        table.insert(summaryParts,tr.name.." ("..TreePoints(state,tr).."): "..(#selected>0 and table.concat(selected,", ") or "None"))
    end
    local summaryText=Label(parent,table.concat(summaryParts,"\n"),10,{0.76,0.81,0.87,1})
    summaryText:SetPoint("TOPLEFT",summaryTitle,"BOTTOMLEFT",0,-8)
    summaryText:SetWidth(870)
    summaryText:SetJustifyH("LEFT")
    parent:SetHeight(765)
    ForeverTalents.Add3Controls(ctx,classKey)
end



-- Talent Builder 3.0 additions are deliberately outside BuildClass to avoid
-- the legacy WoW Lua 200-local-variable limit in that function.
local FB3 = {}
local function FB3DB()
    ForeverDBDatabase = ForeverDBDatabase or {}
    ForeverDBDatabase.talent3 = ForeverDBDatabase.talent3 or {meta={}}
    return ForeverDBDatabase.talent3
end
local function FB3Message(message)
    if DEFAULT_CHAT_FRAME then DEFAULT_CHAT_FRAME:AddMessage("|cff55ccffForever Talents 3.0:|r "..tostring(message)) end
end
local function FB3Button(parent,text,x,y,w,click)
    local b=CreateFrame("Button",nil,parent)
    b:SetSize(w or 110,23); b:SetPoint("TOPLEFT",parent,"TOPLEFT",x,y)
    Background(b,0.06,0.09,0.14,0.98)
    local t=Label(b,text,10,{0.85,0.9,1,1}); t:SetPoint("CENTER")
    b:SetScript("OnClick",click)
    return b
end
local function FB3Window(title,w,h)
    if FB3.popup then FB3.popup:Hide() end
    local f=CreateFrame("Frame",nil,UIParent)
    FB3.popup=f
    f:SetSize(w or 670,h or 500); f:SetPoint("CENTER",UIParent,"CENTER")
    f:SetFrameStrata("FULLSCREEN_DIALOG"); f:SetFrameLevel(500)
    f:EnableMouse(true); f:SetMovable(true); f:RegisterForDrag("LeftButton")
    f:SetScript("OnDragStart",function(self) self:StartMoving() end)
    f:SetScript("OnDragStop",function(self) self:StopMovingOrSizing() end)
    Background(f,0.025,0.035,0.055,0.99)
    local t=Label(f,title,16,{1,0.82,0.25,1}); t:SetPoint("TOPLEFT",f,"TOPLEFT",18,-15)
    FB3Button(f,"CLOSE",(w or 670)-83,-10,65,function() f:Hide() end)
    return f
end
local function FB3Entry(parent,value,x,y,w)
    local e=CreateFrame("EditBox",nil,parent,"InputBoxTemplate")
    e:SetSize(w or 180,23); e:SetPoint("TOPLEFT",parent,"TOPLEFT",x,y)
    e:SetAutoFocus(false); e:SetText(value or "")
    e:SetScript("OnEscapePressed",function(self) self:ClearFocus() end)
    e:SetScript("OnEnterPressed",function(self) self:ClearFocus() end)
    return e
end
local function FB3Lines(parent,lines,x,y,width)
    local t=Label(parent,table.concat(lines,"\n"),11,{0.8,0.86,0.93,1})
    t:SetPoint("TOPLEFT",parent,"TOPLEFT",x,y); t:SetWidth(width or 590)
    t:SetJustifyH("LEFT"); return t
end
local function FB3Meta(key,name)
    local db=FB3DB(); db.meta[key]=db.meta[key] or {}
    db.meta[key][name]=db.meta[key][name] or {category="General",description="",favorite=false}
    return db.meta[key][name]
end
local function FB3Stats(ctx,key)
    local data=ForeverTalents.data[key]; local state=GetState(key)
    local f=FB3Window("BUILD STATISTICS",550,370)
    local lines={"Class: "..data.name,"Level preview: "..tostring(ForeverTalents.previewLevels[key] or 60)}
    local total,selected,highest=0,0,0
    for _,tree in ipairs(data.trees) do
        local pts=TreePoints(state,tree); total=total+pts
        local count,tier=0,0
        for _,talent in ipairs(tree.talents) do
            if RankOf(state,talent.id)>0 then count=count+1; tier=math.max(tier,(talent.row or 0)+1) end
        end
        selected=selected+count; highest=math.max(highest,tier)
        table.insert(lines,tree.name..": "..pts.." points; "..count.." selected talents; tier "..tier)
    end
    table.insert(lines,"Total: "..total.." / "..ForeverTalents.maxPoints)
    table.insert(lines,"Available at preview level: "..math.max(0,math.min(51,(ForeverTalents.previewLevels[key] or 60)-9)-total))
    table.insert(lines,"Overall build completion: "..math.floor(total*100/51).."%")
    table.insert(lines,"Selected talents: "..selected.."  |  Highest tier: "..highest)
    FB3Lines(f,lines,22,-65,500)
end
local function FB3Compare(ctx,key)
    local f=FB3Window("SIDE-BY-SIDE BUILD COMPARISON",790,590)
    local input=FB3Entry(f,"",22,-49,560)
    local left=Label(f,"CURRENT BUILD",13,{1,0.82,0.25,1}); left:SetPoint("TOPLEFT",f,"TOPLEFT",22,-112)
    local right=Label(f,"IMPORTED BUILD",13,{1,0.82,0.25,1}); right:SetPoint("TOPLEFT",f,"TOPLEFT",405,-112)
    FB3Button(f,"COMPARE CODE",600,-49,150,function()
        local other,otherState,err=DecodeBuild(input:GetText())
        if other~=key then FB3Message(err or "Comparison requires a build from the same class."); return end
        local current=GetState(key); local data=ForeverTalents.data[key]
        local a,b={},{},0
        for _,tree in ipairs(data.trees) do
            table.insert(a,tree.name.."  "..TreePoints(current,tree).." points")
            table.insert(b,tree.name.."  "..TreePoints(otherState,tree).." points")
            for _,talent in ipairs(tree.talents) do
                local r1,r2=RankOf(current,talent.id),RankOf(otherState,talent.id)
                if r1>0 or r2>0 then
                    local mark=r1~=r2 and " *" or ""
                    table.insert(a,talent.name.."  "..r1.."/"..talent.maxRank..mark)
                    table.insert(b,talent.name.."  "..r2.."/"..talent.maxRank..mark)
                end
            end
        end
        if f.leftBody then f.leftBody:Hide(); f.rightBody:Hide() end
        f.leftBody=FB3Lines(f,a,22,-140,345)
        f.rightBody=FB3Lines(f,b,405,-140,345)
        FB3Message("Comparison ready. * marks different talent ranks.")
    end)
    FB3Lines(f,{"Paste an FB1 build code above. * indicates differences.","Builds are compared without modifying your active build."},22,-85,740)
end
local function FB3Library(ctx,key)
    local f=FB3Window("ADVANCED BUILD LIBRARY",760,580)
    local db=SavedBuildDB(); db[key]=db[key] or {}
    local names={}; for name in pairs(db[key]) do table.insert(names,name) end
    table.sort(names,function(a,b)
        local ma,mb=FB3Meta(key,a),FB3Meta(key,b)
        if ma.favorite~=mb.favorite then return ma.favorite end
        return a<b
    end)
    local page=FB3.page or 1; local perPage=8
    local maxPage=math.max(1,math.ceil(#names/perPage)); page=math.min(page,maxPage)
    FB3.page=page
    FB3Lines(f,{"Choose a saved build to edit its category, notes, favorite, or name.","Click LOAD to activate it. DUPLICATE creates an independent copy."},18,-49,710)
    for i=(page-1)*perPage+1,math.min(page*perPage,#names) do
        local name=names[i]; local meta=FB3Meta(key,name); local y=-106-((i-1)%perPage)*48
        local display=(meta.favorite and "* " or "")..name.."  ["..meta.category.."]"
        local title=Label(f,display,11,{0.9,0.91,0.98,1}); title:SetPoint("TOPLEFT",f,"TOPLEFT",20,y)
        FB3Button(f,"LOAD",20,y-17,63,function()
            local cls,loaded=DecodeBuild(db[key][name])
            if cls==key then PushHistory(key,GetState(key)); ReplaceState(key,loaded); f:Hide(); ForeverTalents.BuildClass(ctx,key) end
        end)
        FB3Button(f,"EDIT",90,y-17,63,function()
            local editor=FB3Window("EDIT SAVED BUILD",600,330)
            FB3Lines(editor,{"Name", "", "Category (PvE, PvP, Leveling, Raiding, Dungeon, Farming)","", "Description"},20,-48,550)
            local nm=FB3Entry(editor,name,245,-45,320)
            local cat=FB3Entry(editor,meta.category,245,-89,320)
            local desc=FB3Entry(editor,meta.description,245,-133,320)
            FB3Button(editor,meta.favorite and "UNFAVORITE" or "FAVORITE",20,-195,110,function()
                meta.favorite=not meta.favorite; editor:Hide(); FB3Library(ctx,key)
            end)
            FB3Button(editor,"SAVE CHANGES",140,-195,130,function()
                local new=nm:GetText(); if new=="" then new=name end
                if new~=name and db[key][new] then FB3Message("That name already exists."); return end
                if new~=name then
                    db[key][new]=db[key][name]; db[key][name]=nil
                    FB3DB().meta[key][new]=meta; FB3DB().meta[key][name]=nil
                end
                meta.category=cat:GetText(); meta.description=desc:GetText()
                editor:Hide(); FB3Library(ctx,key)
            end)
            FB3Button(editor,"DUPLICATE",280,-195,110,function()
                local copy=name.." Copy"; local n=2
                while db[key][copy] do copy=name.." Copy "..n; n=n+1 end
                db[key][copy]=db[key][name]
                editor:Hide(); FB3Library(ctx,key)
            end)
            FB3Button(editor,"DELETE",400,-195,90,function()
                db[key][name]=nil; FB3DB().meta[key][name]=nil
                editor:Hide(); FB3Library(ctx,key)
            end)
        end)
        FB3Button(f,"COPY",160,y-17,65,function()
            local _,edit=ShowTextDialog("SHARE BUILD CODE",db[key][name],nil,"CLOSE",ctx.PageContent)
            edit:HighlightText()
        end)
    end
    FB3Button(f,"< PREV",20,-510,90,function() FB3.page=math.max(1,page-1); FB3Library(ctx,key) end)
    FB3Button(f,"NEXT >",125,-510,90,function() FB3.page=math.min(maxPage,page+1); FB3Library(ctx,key) end)
    FB3Lines(f,{"Page "..page.." / "..maxPage.."  |  "..#names.." saved builds"},245,-513,360)
end
local function FB3Recommend(ctx,key)
    local f=FB3Window("RECOMMENDED BUILD TEMPLATES",720,490)
    FB3Lines(f,{"Presets supplied with ForeverBrowser; review before applying.","Recommendations are not verified for custom WoW Forever balance."},20,-53,670)
    local presets=PresetLibraryForClass(key)
    if #presets==0 then FB3Lines(f,{"No curated templates are available for this class."},20,-112,660); return end
    for i,preset in ipairs(presets) do
        if i<=9 then
            local y=-114-(i-1)*34
            local label=Label(f,(preset.name or "Build").." ["..(preset.category or "General").."]",10,{0.9,0.9,0.96,1})
            label:SetPoint("TOPLEFT",f,"TOPLEFT",20,y)
            FB3Button(f,"PREVIEW CODE",490,y+3,120,function()
                local code=EncodeBuild(key,ForeverTalents.data[key],preset.state)
                local _,edit=ShowTextDialog("PRESET BUILD CODE",code,nil,"CLOSE",ctx.PageContent); edit:HighlightText()
            end)
            FB3Button(f,"APPLY",620,y+3,72,function()
                PushHistory(key,GetState(key)); ReplaceState(key,CopyState(preset.state))
                f:Hide(); ForeverTalents.BuildClass(ctx,key)
            end)
        end
    end
end
local function FB3Sync(ctx,key)
    local f=FB3Window("CHARACTER TALENT SYNC",630,370)
    FB3Lines(f,{"Read-only scan of talents learned by your current character.","Only matching class and talent names are copied into the builder.","Nothing is spent or changed on your character."},20,-52,585)
    FB3Button(f,"SCAN CHARACTER",20,-140,180,function()
        if not GetNumTalentTabs or not GetNumTalents or not GetTalentInfo then
            FB3Message("Your client does not expose the classic talent API."); return
        end
        local className,classToken=UnitClass("player")
        if string.upper(classToken or "")~=string.upper(key) then FB3Message("Choose your character's class first."); return end
        local result={}; local matched=0; local data=ForeverTalents.data[key]
        local tabs=GetNumTalentTabs() or 0
        for tab=1,math.min(3,tabs) do
            local count=GetNumTalents(tab) or 0
            for idx=1,count do
                local name,icon,tier,column,rank=GetTalentInfo(tab,idx)
                if name and (tonumber(rank) or 0)>0 then
                    for _,tree in ipairs(data.trees) do
                        for _,talent in ipairs(tree.talents) do
                            if string.lower(talent.name)==string.lower(name) then
                                result[talent.id]=math.min(tonumber(rank) or 0,talent.maxRank)
                                matched=matched+1
                            end
                        end
                    end
                end
            end
        end
        if matched==0 then FB3Message("No matching learned talents were found."); return end
        local valid,reason=ValidateState(data,result)
        if not valid then FB3Message("Character talents do not match the builder dataset: "..tostring(reason)); return end
        FB3.pendingSync=result
        FB3Message("Found "..matched.." learned talents. Click COPY TO BUILDER to confirm.")
    end)
    FB3Button(f,"COPY TO BUILDER",215,-140,170,function()
        if not FB3.pendingSync then FB3Message("Scan your character first."); return end
        PushHistory(key,GetState(key)); ReplaceState(key,FB3.pendingSync)
        FB3.pendingSync=nil; f:Hide(); ForeverTalents.BuildClass(ctx,key)
    end)
end
local function FB3Share(ctx,key)
    local f=FB3Window("SHARE BUILD WITH PLAYER",620,340)
    FB3Lines(f,{"Send a build to an online player using WoW addon messages.","Recipient must have ForeverBrowser 3.0 and may accept or decline.","For large builds, copy/export remains the most reliable option."},20,-51,580)
    local target=FB3Entry(f,"",20,-135,240)
    FB3Button(f,"SEND BUILD",280,-135,130,function()
        local name=target:GetText()
        if name=="" then FB3Message("Enter a character name."); return end
        local code=EncodeBuild(key,ForeverTalents.data[key],GetState(key))
        if #code>220 then FB3Message("Build exceeds safe addon message size; use COPY instead."); return end
        if RegisterAddonMessagePrefix then pcall(RegisterAddonMessagePrefix,"FBT3") end
        if C_ChatInfo and C_ChatInfo.RegisterAddonMessagePrefix then pcall(C_ChatInfo.RegisterAddonMessagePrefix,"FBT3") end
        local ok=false
        if C_ChatInfo and C_ChatInfo.SendAddonMessage then ok=pcall(C_ChatInfo.SendAddonMessage,"FBT3",code,"WHISPER",name)
        elseif SendAddonMessage then ok=pcall(SendAddonMessage,"FBT3",code,"WHISPER",name) end
        FB3Message(ok and "Build sent to "..name.." (delivery not confirmed)." or "Addon messaging unavailable in this client.")
    end)
    FB3Button(f,"COPY CODE",425,-135,145,function()
        local _,edit=ShowTextDialog("COPY BUILD CODE",EncodeBuild(key,ForeverTalents.data[key],GetState(key)),nil,"CLOSE",ctx.PageContent)
        edit:HighlightText()
    end)
end
function ForeverTalents.Add3Controls(ctx,key)
    local parent=ctx.PageContent
    local buttons={
        {"BUILD LIBRARY",function() FB3Library(ctx,key) end},
        {"VISUAL COMPARE",function() FB3Compare(ctx,key) end},
        {"RECOMMENDATIONS",function() FB3Recommend(ctx,key) end},
        {"STATISTICS",function() FB3Stats(ctx,key) end},
        {"SHARE BUILD",function() FB3Share(ctx,key) end},
        {"SYNC CHARACTER",function() FB3Sync(ctx,key) end},
    }
    for i,item in ipairs(buttons) do
        FB3Button(parent,item[1],20+(i-1)*147,-745,138,item[2])
    end
    parent:SetHeight(810)
end
-- Accept/decline incoming talent builds. No automatic changes are made.
if not ForeverTalents._FB3Comm then
    ForeverTalents._FB3Comm=CreateFrame("Frame")
    ForeverTalents._FB3Comm:RegisterEvent("CHAT_MSG_ADDON")
    ForeverTalents._FB3Comm:SetScript("OnEvent",function(self,event,prefix,message,channel,sender)
        if prefix~="FBT3" then return end
        local key,state=DecodeBuild(message)
        if not key then return end
        local f=FB3Window("INCOMING TALENT BUILD",550,290)
        FB3Lines(f,{"From: "..tostring(sender),"Class: "..ForeverTalents.data[key].name,
            "The build will only be imported into the calculator.","Your character's talents will not be modified."},20,-56,500)
        FB3Button(f,"ACCEPT",20,-195,110,function()
            PushHistory(key,GetState(key)); ReplaceState(key,state)
            f:Hide(); FB3Message("Build accepted for "..ForeverTalents.data[key].name..". Open that class to view it.")
        end)
        FB3Button(f,"DECLINE",150,-195,110,function() f:Hide() end)
    end)
end


-- ForeverBrowser Talent Builder 3.1: optional planning tools.
-- Existing talents, cinematic class screen, artwork and preset file are untouched.
local function FB31Store()
    local db=FB3DB()
    db.recommended=db.recommended or {}
    return db.recommended
end
local function FB31Key(p)
    return p.code or p.name
end
local function FB31Prefs(key,p)
    local db=FB31Store(); db[key]=db[key] or {}
    local id=FB31Key(p); db[key][id]=db[key][id] or {favorite=false,rating=0}
    return db[key][id]
end
local function FB31Summary(key,p)
    local data=ForeverTalents.data[key]
    local parts={}
    for _,tree in ipairs(data.trees) do
        table.insert(parts,tree.name.." "..TreePoints(p.state,tree))
    end
    return table.concat(parts," / ")
end
-- Compact, readable build-details layout. Keep all existing preset and
-- saved-preference APIs intact; only the presentation is changed.
local function FB31Details(ctx,key,p,back)
    local f=FB3Window("BUILD DETAILS",790,495)
    local pref=FB31Prefs(key,p)
    local classData=ForeverTalents.data[key]
    local function Text(parent,value,x,y,width,size,color)
        local t=Label(parent,tostring(value or ""),size or 11,color or {0.82,0.88,0.95,1})
        t:SetPoint("TOPLEFT",parent,"TOPLEFT",x,y)
        t:SetWidth(width); t:SetJustifyH("LEFT")
        return t
    end
    local function Panel(x,y,w,h)
        local panel=CreateFrame("Frame",nil,f)
        panel:SetPoint("TOPLEFT",f,"TOPLEFT",x,y)
        panel:SetSize(w,h)
        Background(panel,0.075,0.105,0.15,1)
        return panel
    end
    local function Short(value,maxLen)
        value=tostring(value or "")
        if #value>maxLen then return string.sub(value,1,maxLen-3).."..." end
        return value
    end
    local name=tostring(p.name or "Unnamed build")
    local category=string.upper(tostring(p.category or "GENERAL"))
    local author=tostring(p.author or "Unknown")
    local description=tostring(p.description or "")
    local source=string.match(description,"https?://[^%s]+")
    local notes=description
    if source then notes=string.gsub(notes,source,"") end
    notes=string.gsub(notes,"^[%s%p]+","")
    notes=string.gsub(notes,"[%s%p]+$","")
    if notes=="" then notes="No additional notes were provided for this build." end

    -- Header: full name wraps within a dedicated area instead of running into
    -- the close button or spilling into the talent summary.
    Text(f,Short(name,115),20,-49,745,14,{1,0.84,0.36,1})
    Text(f,classData.name.."  |  "..category.."  |  Source: "..Short(author,38),20,-91,742,10,{0.7,0.79,0.9,1})

    -- Three independent tree cards with no text overlap.
    for i,tree in ipairs(classData.trees) do
        local x=20+(i-1)*254
        local card=Panel(x,-118,244,73)
        Text(card,Short(tree.name,28),12,-10,220,11,{0.78,0.85,0.95,1})
        Text(card,tostring(TreePoints(p.state,tree)).." POINTS",12,-34,220,16,{1,0.82,0.32,1})
    end

    -- Notes are kept separate from the source link, with a fixed area.
    local info=Panel(20,-204,750,112)
    Text(info,"BUILD INFORMATION",13,-10,715,11,{1,0.82,0.32,1})
    Text(info,Short(notes,240),13,-33,714,11,{0.84,0.89,0.95,1})
    if source then
        Text(info,"SOURCE: "..Short(source,106),13,-84,714,10,{0.58,0.77,0.97,1})
    else
        Text(info,"SOURCE: "..Short(author,85),13,-84,714,10,{0.58,0.77,0.97,1})
    end

    local preferences=Panel(20,-327,750,64)
    Text(preferences,"MY BUILD",13,-9,100,10,{1,0.82,0.32,1})
    local favoriteButton=FB3Button(preferences,pref.favorite and "* FAVORITED" or "ADD FAVORITE",108,-8,133,function()
        pref.favorite=not pref.favorite
        -- Redraw this one popup without stacking duplicate windows.
        FB31Details(ctx,key,p,back)
    end)
    Text(preferences,"MY RATING",263,-13,92,10,{0.75,0.83,0.92,1})
    for n=1,5 do
        FB3Button(preferences,(n<=pref.rating and "* " or "")..tostring(n),353+(n-1)*72,-8,62,function()
            pref.rating=n
            FB31Details(ctx,key,p,back)
        end)
    end
    Text(preferences,pref.rating>0 and ("Rated "..pref.rating.." / 5") or "Not rated",263,-42,250,10,{0.68,0.77,0.87,1})

    -- The action bar is clearly separated from preferences and warnings.
    FB3Button(f,"PREVIEW CODE",20,-405,150,function()
        local _,edit=ShowTextDialog("RECOMMENDED BUILD CODE",p.code,nil,"CLOSE",ctx.PageContent)
        edit:HighlightText()
    end)
    FB3Button(f,"APPLY TO PLANNER",183,-405,191,function()
        local cls,loaded,why=DecodeBuild(p.code)
        if cls~=key or not loaded then
            FB3Message("Cannot apply: "..tostring(why or "invalid build"))
            return
        end
        PushHistory(key,GetState(key)); ReplaceState(key,loaded)
        f:Hide(); ForeverTalents.BuildClass(ctx,key)
    end)
    FB3Button(f,"BACK TO RESULTS",388,-405,176,function()
        f:Hide(); back()
    end)
    Text(f,"Community plans are unverified. Apply changes the planner only, not your character.",20,-454,745,10,{0.69,0.76,0.85,1})
end
-- Polished, scrollable Recommended Builds browser. All data stays in the
-- existing preset file and player preferences; no migrations are necessary.
local function FB31Short(value,limit)
    value=tostring(value or "")
    if #value>limit then return string.sub(value,1,limit-3).."..." end
    return value
end
local function FB31Recommendations(ctx,key,category,query,favorites,page,spec)
    category=category or "ALL"; query=query or ""; spec=spec or "ALL"
    local presets=PresetLibraryForClass(key)
    local matches={}; local categories={"ALL"}; local seen={ALL=true}
    local specs={"ALL"}
    for _,tree in ipairs(ForeverTalents.data[key].trees) do
        table.insert(specs,tree.name)
    end
    for _,p in ipairs(presets) do
        local cat=string.upper(tostring(p.category or "GENERAL"))
        if not seen[cat] then seen[cat]=true; table.insert(categories,cat) end
        local pref=FB31Prefs(key,p)
        local hay=string.lower(tostring(p.name).." "..tostring(p.description).." "..tostring(p.author).." "..cat)
        local bestName,bestPoints=nil,-1
        for _,tree in ipairs(ForeverTalents.data[key].trees) do
            local pts=TreePoints(p.state,tree)
            if pts>bestPoints then bestPoints=pts; bestName=tree.name end
        end
        if (category=="ALL" or category==cat)
           and (spec=="ALL" or spec==bestName)
           and (not favorites or pref.favorite)
           and (query=="" or string.find(hay,string.lower(query),1,true)) then
            table.insert(matches,p)
        end
    end
    table.sort(matches,function(a,b)
        local af,bf=FB31Prefs(key,a).favorite,FB31Prefs(key,b).favorite
        if af~=bf then return af end
        return string.lower(a.name)<string.lower(b.name)
    end)

    local f=FB3Window("RECOMMENDED BUILDS",850,650)
    local subtitle=Label(f,ForeverTalents.data[key].name.."  |  "..#matches.." builds found  |  "..#presets.." available for this class",11,{0.67,0.75,0.85,1})
    subtitle:SetPoint("TOPLEFT",f,"TOPLEFT",20,-45)
    local search=FB3Entry(f,query,20,-77,440)
    FB3Button(f,"SEARCH",475,-77,100,function()
        FB31Recommendations(ctx,key,category,search:GetText(),favorites,1,spec)
    end)
    FB3Button(f,"CLEAR",590,-77,85,function()
        FB31Recommendations(ctx,key,"ALL","",false,1,"ALL")
    end)
    FB3Button(f,favorites and "* FAVORITES" or "FAVORITES",690,-77,135,function()
        FB31Recommendations(ctx,key,category,search:GetText(),not favorites,1,spec)
    end)
    local ci,si=1,1
    for i,c in ipairs(categories) do if c==category then ci=i end end
    for i,s in ipairs(specs) do if s==spec then si=i end end
    FB3Button(f,"TYPE: "..FB31Short(category,17),20,-118,252,function()
        FB31Recommendations(ctx,key,categories[ci==#categories and 1 or ci+1],search:GetText(),favorites,1,spec)
    end)
    FB3Button(f,"SPEC: "..FB31Short(spec,17),288,-118,252,function()
        FB31Recommendations(ctx,key,category,search:GetText(),favorites,1,specs[si==#specs and 1 or si+1])
    end)
    local hint=Label(f,"Click a filter to cycle options",10,{0.57,0.65,0.76,1})
    hint:SetPoint("TOPLEFT",f,"TOPLEFT",560,-125)

    -- A dedicated scroll child keeps every row inside its own opaque card.
    -- Nothing is anchored to the parent beyond the visible viewport.
    local viewport=CreateFrame("ScrollFrame",nil,f,"UIPanelScrollFrameTemplate")
    viewport:SetPoint("TOPLEFT",f,"TOPLEFT",20,-160)
    viewport:SetSize(790,404)
    local content=CreateFrame("Frame",nil,viewport)
    content:SetWidth(766)
    content:SetHeight(math.max(404,#matches*102+6))
    viewport:SetScrollChild(content)
    if #matches==0 then
        local empty=Label(content,"No builds match these filters. Try CLEAR or another specialization.",12,{0.8,0.84,0.9,1})
        empty:SetPoint("TOPLEFT",content,"TOPLEFT",18,-40)
        empty:SetWidth(700)
    end
    for i,p in ipairs(matches) do
        local pref=FB31Prefs(key,p)
        local card=CreateFrame("Frame",nil,content)
        card:SetPoint("TOPLEFT",content,"TOPLEFT",3,-(i-1)*102-3)
        card:SetSize(754,95)
        Background(card,0.09,0.13,0.19,1)
        local strip=card:CreateTexture(nil,"ARTWORK")
        strip:SetTexture("Interface\\Buttons\\WHITE8X8")
        strip:SetVertexColor(0.83,0.64,0.22,1)
        strip:SetPoint("TOPLEFT",card,"TOPLEFT",0,0)
        strip:SetSize(3,95)
        local nm=Label(card,FB31Short(p.name,76),12,{1,0.84,0.35,1})
        nm:SetPoint("TOPLEFT",card,"TOPLEFT",14,-11)
        nm:SetWidth(500); nm:SetJustifyH("LEFT")
        local categoryText=Label(card,"["..FB31Short(p.category,20).."]  "..FB31Short(p.author,38),10,{0.75,0.82,0.91,1})
        categoryText:SetPoint("TOPLEFT",card,"TOPLEFT",14,-36)
        categoryText:SetWidth(500); categoryText:SetJustifyH("LEFT")
        local summary=Label(card,FB31Short(FB31Summary(key,p),85),10,{0.66,0.74,0.84,1})
        summary:SetPoint("TOPLEFT",card,"TOPLEFT",14,-57)
        summary:SetWidth(500); summary:SetJustifyH("LEFT")
        FB3Button(card,pref.favorite and "* SAVED" or "FAVORITE",534,-8,94,function()
            pref.favorite=not pref.favorite
            FB31Recommendations(ctx,key,category,search:GetText(),favorites,1,spec)
        end)
        FB3Button(card,"DETAILS",534,-42,94,function()
            FB31Details(ctx,key,p,function()
                FB31Recommendations(ctx,key,category,search:GetText(),favorites,1,spec)
            end)
        end)
        FB3Button(card,"APPLY",640,-42,96,function()
            local cls,state,why=DecodeBuild(p.code)
            if cls~=key or not state then
                FB3Message("Invalid preset: "..tostring(why or "class mismatch")); return
            end
            PushHistory(key,GetState(key)); ReplaceState(key,state)
            f:Hide(); ForeverTalents.BuildClass(ctx,key)
        end)
        local rating=Label(card,pref.rating>0 and (pref.rating.." / 5 stars") or "Not rated",10,{0.72,0.79,0.88,1})
        rating:SetPoint("TOPLEFT",card,"TOPLEFT",640,-17)
        rating:SetWidth(100)
    end
    local footer=Label(f,"Scroll to browse  |  Favorites and ratings are personal  |  Applying only changes the planner",10,{0.7,0.78,0.87,1})
    footer:SetPoint("TOPLEFT",f,"TOPLEFT",22,-583)
    footer:SetWidth(800); footer:SetJustifyH("LEFT")
    FB3Button(f,"CLOSE",710,-610,115,function() f:Hide() end)
end
local function FB31Guide(ctx,key)
    local f=FB3Window("LEVEL-BY-LEVEL TALENT GUIDE",790,555)
    local state=GetState(key); local data=ForeverTalents.data[key]
    local steps={}
    -- Simulate a legal point allocation, adding a point only if the intermediate
    -- state passes the same tier and prerequisite validator as the calculator.
    local simulated={}
    local remaining=TotalPoints(state)
    for level=10,math.min(60,9+remaining) do
        local chosen=nil
        for _,tree in ipairs(data.trees) do
            for _,talent in ipairs(tree.talents) do
                if RankOf(simulated,talent.id)<RankOf(state,talent.id) then
                    local candidate=CopyState(simulated)
                    candidate[talent.id]=RankOf(candidate,talent.id)+1
                    local valid=ValidateState(data,candidate)
                    if valid then chosen={talent=talent,tree=tree}; break end
                end
            end
            if chosen then break end
        end
        if not chosen then break end
        simulated[chosen.talent.id]=RankOf(simulated,chosen.talent.id)+1
        table.insert(steps,"Level "..level..": "..chosen.tree.name.." / "..chosen.talent.name.." ("..simulated[chosen.talent.id].."/"..chosen.talent.maxRank..")")
    end
    local index=1
    local label=FB3Lines(f,{""},22,-93,735)
    local function render()
        local lines={"Current planner: "..TotalPoints(state).." allocated points.",
            "This is a suggested legal order for the current build, not a claimed optimal leveling route.",""}
        if #steps==0 then
            table.insert(lines,"Allocate talents in the planner first, then reopen this guide.")
        else
            for i=math.max(1,index-3),math.min(#steps,index+9) do
                table.insert(lines,(i==index and "> " or "  ")..steps[i])
            end
            table.insert(lines,"")
            table.insert(lines,"Step "..index.." / "..#steps)
        end
        label:SetText(table.concat(lines,"\n"))
    end
    FB3Button(f,"< PREVIOUS",22,-465,145,function() index=math.max(1,index-1); render() end)
    FB3Button(f,"NEXT POINT >",185,-465,145,function() index=math.min(#steps,index+1); render() end)
    FB3Button(f,"COPY BUILD CODE",350,-465,165,function()
        local _,edit=ShowTextDialog("LEVELING BUILD CODE",EncodeBuild(key,data,state),nil,"CLOSE",ctx.PageContent)
        edit:HighlightText()
    end)
    render()
end
-- Replace only the lower utility row; all original tools and saved data remain.
function ForeverTalents.Add3Controls(ctx,key)
    local parent=ctx.PageContent
    local buttons={
        {"BUILD LIBRARY",function() FB3Library(ctx,key) end},
        {"COMPARE",function() FB3Compare(ctx,key) end},
        {"RECOMMENDED 2.0",function() FB31Recommendations(ctx,key) end},
        {"LEVEL GUIDE",function() FB31Guide(ctx,key) end},
        {"STATISTICS",function() FB3Stats(ctx,key) end},
        {"SHARE",function() FB3Share(ctx,key) end},
        {"SYNC",function() FB3Sync(ctx,key) end},
    }
    for i,item in ipairs(buttons) do
        local row=math.floor((i-1)/4); local col=(i-1)%4
        FB3Button(parent,item[1],20+col*215,-745+row*32,205,item[2])
    end
    parent:SetHeight(845)
end
